def index(self, key):
        """ Return the index of the given item.

        :param key: a key
        :return: index
        :rtype: int
        """
        for i, v in enumerate(self):
            if v == key:
                return i
        return -1

def values(self, *keys):
        """Return the values of the record, optionally filtering to include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        if not keys:
            return list(self.values())
        else:
            return [self[k] for k in keys]

def data(self, *keys):
    """Return the keys and values of this record as a dictionary, optionally including only certain values by index or key. Keys provided in the items that are not in the record will be inserted with a value of `None`; indexes provided that are out of bounds will trigger an `IndexError`.

    :param keys: indexes or keys of the items to include; if none are provided, all values will be included.
    :return: dictionary of values, keyed by field name.
    :raises: :exc:`IndexError` if an out-of-bounds index is specified.
    """

    data = {}

    if not keys:
        # include all fields if no keys were provided
        for key in self.fields:
            value = getattr(self, key)
            if value is not None:
                data[key] = value
    else:
        # only include fields specified by key
        for key in keys:
            if isinstance(key, int):
                # key is an index
                try:
                    value = self[key]
                except IndexError:
                    raise IndexError(f"Index {key} is out of bounds for this record.")
            else:
                # key is a field name
                value = getattr(self, key)
            if value is not None:
                data[key] = value

    return data

