def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorate(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if key is None:
                key = args + kwargs
            else:
                key = key(*args, **kwargs)

            if not lock:
                lock = threading.Lock()
            with lock:
                cache_key = (func, key)
                if cache_key in cache:
                    return cache[cache_key]

                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorate

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """
    Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    Parameters:
        maxsize (int): The maximum number of items to cache.
        ttl (int): The time-to-live (TTL) value in seconds.
        timer (Callable): A callable that returns a timestamp for getting the current time.
        typed (bool): Whether to use a typed dict for caching.

    Returns:
        Callable: The decorated function.
    """
    class Cache(OrderedDict):
        def __init__(self, maxsize, ttl, timer, typed):
            super().__init__()
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def __getitem__(self, key):
            value = super().__getitem__(key)
            self.move_to_end(key)
            return value

        def __setitem__(self, key, value):
            super().__setitem__(key, value)
            if len(self) > self.maxsize:
                oldest = self.popitem(last=False)
                print(f'Evicted {oldest[0]}')
            self.move_to_end(key)

        def get_ttl_value(self):
            return time.monotonic() - self.ttl

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items()))
            if key not in cache:
                value = func(*args, **kwargs)
                if cache.typed:
                    cache[key] = (value, time.monotonic())
                else:
                    cache[key] = value
                    print(f'Cached {key}')
                return value
            else:
                if cache.typed:
                    value, timestamp = cache[key]
                    if time.monotonic() - timestamp > cache.get_ttl_value():
                        return value
                else:
                    if time.monotonic() - cache[key] > cache.get_ttl_value():
                        return value
            return cache[key]
        return wrapper

    cache = Cache(maxsize, ttl, timer, typed)
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    class LFUCache(dict):
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.access_count = {}

        def __getitem__(self, key):
            if key in self:
                value = dict.__getitem__(self, key)
                if self.typed:
                    type_key = type(value)
                    if type_key not in self.access_count:
                        self.access_count[type_key] = 0
                    self.access_count[type_key] += 1
                else:
                    self.access_count[key] += 1

            return value

        def __setitem__(self, key, value):
            if self.typed:
                type_key = type(value)
                if type_key not in self.access_count:
                    self.access_count[type_key] = 0
            else:
                self.access_count[key] = 0

            dict.__setitem__(self, key, value)

            if len(self) > self.maxsize:
                self.popitem()

    def wrapper(func):
        func = args_to_dict(func)
        key = hash(tuple([func.func_code, func.__closure__, sorted(func.defaults.items())]))

        cache = LFUCache(maxsize, typed)
        cache[key] = func

        def wrapper(*args):
            key = hash(tuple([key, args]))
            value = cache[key]
            return value()

        wrapper.cache = cache
        return wrapper

    return wrapper

