def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    default_schema = {}
    for key, value in manifest_dict.items():
        if not isinstance(value, list):
            default_schema[key] = None
        elif first_level and key in ["metadata", "status"]:
            default_schema[key] = json.loads(json.dumps(value, indent=4))
        else:
            default_schema[key] = []
            for item in value:
                if isinstance(item, dict):
                    default_schema[key].append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    default_schema[key].append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    default_schema[key].append(None)
    return default_schema

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if not resource.observer_schema:
            resource.observer_schema = generate_observer_schema(resource)

        for subresource in resource.spec.subresources:
            if not subresource.observer_schema:
                subresource.observer_schema = generate_observer_schema(subresource)

