def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    status = self.validation_log.status
    prefix += ' ' if prefix else ''
    out = ''
    if status == ValidationStatus.FAILED:
        out += prefix + 'Total: %d\n' % len(self.validation_log.failed_checks)
        for check in self.validation_log.failed_checks:
            out += prefix + check.name + ':\n'
            out += prefix + '  Entity: %s\n' % check.entity.id
            out += prefix + '  Message: %s\n' % check.message
    elif status == ValidationStatus.WARNING:
        out += prefix + 'Total: %d\n' % len(self.validation_log.warning_checks)
        for check in self.validation_log.warning_checks:
            out += prefix + check.name + ':\n'
            out += prefix + '  Entity: %s\n' % check.entity.id
            out += prefix + '  Message: %s\n' % check.message
    else:
        out += prefix + 'Your model passed all validation checks.\n'
    return out

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    # Check the type value first to determine the specification version
    if extract_spec_version and 'type' in inventory:
        type_value = inventory['type']
        if type_value in SPEC_VERSIONS:
            spec_version = SPEC_VERSIONS[type_value]
        else:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version

    # Validate the inventory against the specification version
    if spec_version == SpecificationVersion.VERSION_1_0:
        # Validate version_1_0 specific fields
        if 'recognition-info' not in inventory or 'cycle-time' not in inventory or 'latency' not in inventory:
            raise ValidationError("Inventory is missing required fields for version 1.0")
    elif spec_version == SpecificationVersion.VERSION_1_1:
        # Validate version_1_1 specific fields
        if 'recognition-info' not in inventory or 'cycle-time' not in inventory or 'latency' not in inventory or 'quality-metrics' not in inventory:
            raise ValidationError("Inventory is missing required fields for version 1.1")
    elif spec_version == SpecificationVersion.VERSION_1_2:
        # Validate version_1_2 specific fields
        if 'recognition-info' not in inventory or 'cycle-time' not in inventory or 'latency' not in inventory or 'quality-metrics' not in inventory or 'production-info' not in inventory:
            raise ValidationError("Inventory is missing required fields for version 1.2")
    else:
        raise ValidationError("Unsupported specification version")

    # Validate the type of each field
    for field, field_value in inventory.items():
        if field in ['type', 'recognition-info', 'cycle-time', 'latency', 'quality-metrics', 'production-info']:
            # Validate each field value
            if field == 'type':
                if field_value not in SPEC_VERSIONS.keys():
                    raise ValueError("Invalid inventory type")
            elif field == 'recognition-info':
                if not isinstance(field_value, dict):
                    raise TypeError("Expected a dict for recognition-info, got " + type(field_value).__name__)
                # Validate each field value in recognition-info
                for recognition_info_field, recognition_info_value in field_value.items():
                    if recognition_info_field == 'required-traits':
                        for trait in recognition_info_value:
                            if trait not in ALLOWED_TRAITS:
                                raise ValueError("Invalid recognized trait " + trait)
                    elif recognition_info_field == 'preferred-environments':
                        for environment in recognition_info_value:
                            if environment not in ALLOWED_ENVIRONMENTS:
                                raise ValueError("Invalid recognized environment " + environment)
                    elif recognition_info_field == 'suggested-languages':
                        for language in recognition_info_value:
                            if language not in ALLOWED_LANGUAGES:
                                raise ValueError("Invalid recognized language " + language)
            elif field == 'cycle-time':
                if not isinstance(field_value, int):
                    raise TypeError("Expected an int for cycle-time, got " + type(field_value).__name__)
            elif field == 'latency':
                if not isinstance(field_value, int):
                    raise TypeError("Expected an int for latency, got " + type(field_value).__name__)
            elif field == 'quality-metrics':
                if not isinstance(field_value, dict):
                    raise TypeError("Expected a dict for quality-metrics, got " + type(field_value).__name__)
                # Validate each field value in quality-metrics
                for metric_name, metric_value in field_value.items():
                    if metric_name not in ALLOWED_METRICS:
                        raise ValueError("Invalid quality metric " + metric_name)
                    if not isinstance(metric_value, dict):
                        raise TypeError("Expected a dict for quality metric " + metric_name + ", got " + type(field_value).__name__)
                    # Validate each field value in quality metric
                    for quality_metric_field, quality_metric_value in metric_value.items():
                        if quality_metric_field == 'trait':
                            if quality_metric_value not in ALLOWED_TRAITS:
                                raise ValueError("Invalid quality metric trait " + quality_metric_value)
                        elif quality_metric_field == 'type':
                            if quality_metric_value not in ALLOWED_METRIC_TYPES:
                                raise ValueError("Invalid quality metric type " + quality_metric_value)
                        else:
                            raise ValueError("Unknown field " + quality_metric_field + " in quality metric")
            elif field == 'production-info':
                if not isinstance(field_value, dict):
                    raise TypeError("Expected a dict for production-info, got " + type(field_value).__name__)
                # Validate each field value in production-info
                for production_info_field, production_info_value in field_value.items():
                    if production_info_field == 'production-type':
                        if production_info_value not in ALLOWED_PRODUCTION_TYPES:
                            raise ValueError("Invalid production type " + production_info_value)
                    elif production_info_field == 'source':
                        if production_info_value not in ALLOWED_SOURCES:
                            raise ValueError("Invalid source " + production_info_value)
                    else:
                        raise ValueError("Unknown field " + production_info_field + " in production-info")
            else:
                raise ValueError("Unknown field " + field)
        else:
            raise ValueError("Unknown field " + field)

    return inventory

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior must be an InventoryValidator object")
    if self.version > prior.version:
        raise ValueError(f"prior inventory {prior.version} is later than current inventory {self.version}")
    if self.ters < prior.ters:
        raise ValueError(f"prior inventory {prior.ters} has more TERs than current inventory {self.ters}")

def get_logical_path_map(inventory, version):
    """
    Return a dictionary: logical_path_in_state -> set(content_files)

    content_files includes references to duplicate files in 
    later versions than the version being described
    """
    # Initialize the map
    logical_path_map = {}

    # Iterate over the contents of the version
    for state in version.states:
        # Iterate over the contents of the state
        for content in state.contents:
            # Get the path of the content on disk
            content_path = content.get_path()

            # Get the logical path of the content
            logical_path = content.get_logical_path()

            # Add the path to the map, using the logical path as the key
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = {content_path}
            else:
                logical_path_map[logical_path].add(content_path)

    # Return the map
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check that the fixity block is at the root of the inventory
    if not isinstance(fixity, dict) or "root" in fixity:
        raise ValueError("Fixity block must be at the root of the inventory")

    # Check that the fixity block contains a manifest file
    if "manifest" not in fixity:
        raise ValueError("Fixity block must contain a manifest file")

    # Check that the manifest file exists
    manifest_file = manifest_files.get(fixity["manifest"])
    if not manifest_file:
        raise ValueError("Manifest file does not exist")

    # Check that the manifest file contains the same number of files as the fixity block
    # Note: This assumes the manifest file contains one file per line
    with open(manifest_file) as f:
        num_manifest_files = len(f.readlines())
    if num_manifest_files != len(fixity):
        raise ValueError("Number of files in manifest does not match number of files in fixity block")

    # Check that each file in the manifest is referenced in the fixity block
    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File '{file}' in manifest is not referenced in fixity block")

    # Check that each file in the manifest has a matching hash in the fixity block
    for file in manifest_files:
        if not file in fixity or not isinstance(fixity[file], str):
            raise ValueError(f"Missing or invalid hash for file '{file}' in manifest")

    # Check that the hashes in the fixity block are all case-insensitive
    # Note: This assumption is not completely accurate, hashes can be uppercase
    for file in fixity:
        if not fixity[file].lower() == fixity[file]:
            raise ValueError(f"Hash for file '{file}' in manifest is not lowercase")

    # Check that the files in the manifest are all case-insensitive
    # Note: This assumption is not completely accurate, file names can be uppercase
    for file in manifest_files:
        if not file.lower() == file:
            raise ValueError(f"File '{file}' in manifest is not lowercase")

    # Check that the fixity block contains a checksum
    if "checksum" not in fixity:
        raise ValueError("Fixity block must contain a checksum")

    # Check that the checksum is a valid hash algorithm
    if not isinstance(fixity["checksum"], str):
        raise ValueError("Checksum must be a string")
    if not len(fixity["checksum"]) == 64:
        raise ValueError("Checksum must be a 64-character string")
    if not fixity["checksum"].isalnum():
        raise ValueError("Checksum must be alphanumeric")

    # Check that the checksum matches the hash of the manifest file
    manifest_hash = hashlib.sha256(open(manifest_file, "rb").read()).hexdigest()
    if manifest_hash != fixity["checksum"]:
        raise ValueError("Manifest hash does not match fixity block checksum")

def _explore_folder(folder):
    packages = {}
    for path in glob.glob(os.path.join(folder, '**/*')):
        if os.path.isfile(path):
            name, ext = os.path.splitext(os.path.basename(path))
            if ext == '.xml':
                packages[name] = etree.parse(path).getroot()
    return packages

