def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    new_args = []
    for arg in args:
        if type(arg) == list or type(arg) == tuple:
            # arg is a binary operation
            if arg[0] == "&":
                if arg[1] == "|":
                    # absorption
                    new_args.append(arg[1])
                else:
                    # negated absorption
                    new_args.append("&".join([arg[1], arg[2]]))
            else:
                new_args.append([arg[0], arg[1], absorb(arg[2])])
        else:
            new_args.append(arg)

    return new_args

