def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list):
        commands = [commands]
    for cmd in commands:
        if not isinstance(cmd, str):
            raise ValueError("Command must be a string or a list of strings, got {!r}".format(cmd))
    if args is not None and not isinstance(args, list):
        args = [args]
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("Working directory must be a string, got {!r}".format(cwd))
    if env is not None and not isinstance(env, dict):
        raise ValueError("Environment must be a dict, got {!r}".format(env))

    if verbose:
        print("Running command: {}".format(commands))
        print("Args: {}".format(args))

    # Start the process
    p = subprocess.Popen(commands, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, env=env)

    # Read from stdout and stderr
    stdout, stderr = p.communicate(input=args)

    if not hide_stderr:
        if stderr:
            print(stderr.decode())
    if p.returncode != 0 and verbose:
        print("Command failed")

    return p.returncode, stdout

