def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    root_inventory = self.inventory

    for version in version_dirs:
        inventory = self.inventory(version)

        # Each version SHOULD have an inventory up to that point.
        if not inventory:
            raise ValidationError(f"Inventory not found for version {version}.")

        # Keep a record of any content digests different from those in the root inventory
        # so that we can also check them when validating the content.
        different_digests = {}
        for name in inventory.keys():
            root_digest = root_inventory.get(name)
            if root_digest != inventory.get(name):
                different_digests[name] = inventory[name]

        # Verify the existence and content of the files referenced in the inventory.
        for name in inventory.keys():
            path = inventory.metadata(name)
            if not path:
                raise ValidationError(f"Metadata not found for {name}.""")
            elif not (path.exists()):
                raise ValidationError(f"Metadata not found for {name}.""")

        # Verify that the inventory has no digests that are different from the root inventory.
        if different_digests:
            raise ValidationError("Inventories have different digests: " + str(different_digests))

        # Successfully validated this version.
        logger.info(f"Successfully validated version {version}.")

