                    result[tag.id][new_k.id] = new_val
                else:
                    result[tag.id][k.id] = k
                result[tag.id] = ruamel.yaml.nodes.MappingNode(tag.tag, result[tag.id], tag.start_mark)
            if key.id in [n[0].id for n in result]:
