                    required_args.append(option["name"])
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """

    if len(args) > self.max_length:
        raise ValueError(f"The maximum length of arguments is {self.max_length}, but {len(args)} were received.")

def validate_choices(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in self.CHOICES:
            raise ValueError("The value of argument '{}' must be one of the available choices: {}".format(arg, self.CHOICES))

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        for arg in args:
            if arg < self.min_args or arg > self.max_args:
                raise ValueError(f"The value of {arg} is outside the allowed range.")

def get_nested_custom_and_control_args(args):
        """Split input arguments to control nested and custom.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        for arg in args:
            if arg.startswith('control_'):
                control_args[arg] = args[arg]
            elif arg.startswith('nested_'):
                nested_args[arg] = args[arg]
            else:
                raise ValueError(f"Unsupported argument {arg}")
        return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if extra_vars is not None:
            for key, val in extra_vars:
                vars_dict[key] = val

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os.path
    import glob
    from lxml import etree

    spec_file = os.path.join(plugin_dir, "plugin.xml")
    tree = etree.parse(spec_file)
    root = tree.getroot()

    plugin_info = {}

    for elem in root.iterfind(".//"):
        plugin_info[elem.tag] = elem.text

    for elem in root.iterfind(".//"):
        if elem.tag == "id":
            plugin_info["id"] = elem.text
        elif elem.tag == "name":
            plugin_info["name"] = elem.text
        elif elem.tag == "vendor":
            plugin_info["vendor"] = elem.text
        elif elem.tag == "version":
            plugin_info["version"] = elem.text
        elif elem.tag == "description":
            plugin_info["description"] = elem.text
        elif elem.tag == "namespace":
            plugin_info["namespace"] = elem.text
        elif elem.tag == "python-module":
            plugin_info["python-module"] = elem.text
        elif elem.tag == "requires":
            plugin_info["requires"] = elem.text
        elif elem.tag == "license":
            plugin_info["license"] = elem.text
        elif elem.tag == "proprietary":
            plugin_info["proprietary"] = elem.text
        elif elem.tag == "hidden":
            plugin_info["hidden"] = elem.text

    return plugin_info

def strip_root(path, root):
    if path.startswith(root):
        return path[len(root):]
    else:
        raise ValueError(f"{path!r} is not under {root!r}")
